package com.foodshare.controller;
import com.foodshare.model.*;import com.foodshare.repository.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.transaction.annotation.Transactional;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/donations") @Transactional public class DonationController{
 private final DonationRepository donations;private final UserRepository users;public DonationController(DonationRepository d,UserRepository u){donations=d;users=u;}
 @GetMapping public List<Donation> all(){return donations.findByStatus("AVAILABLE");}@GetMapping("/my") public List<Donation> mine(Principal p){return donations.findByDonorId(users.findByEmail(p.getName()).orElseThrow().getId());}@GetMapping("/{id}") public Donation one(@PathVariable Integer id){return donations.findById(id).orElseThrow();}
 @PostMapping public Donation create(@RequestBody Donation d,Principal p){if(d.getFoodName()==null||d.getFoodName().isBlank()||d.getLocation()==null||d.getLocation().isBlank()||d.getQuantity()==null||d.getQuantity()<1)throw new IllegalArgumentException("Food name, location and a quantity greater than zero are required.");d.setDonor(users.findByEmail(p.getName()).orElseThrow());d.setStatus("AVAILABLE");return donations.save(d);}
 @PutMapping("/{id}") public Donation update(@PathVariable Integer id,@RequestBody Donation input,Principal p){Donation d=donations.findById(id).orElseThrow();if(!d.getDonor().getEmail().equals(p.getName()))throw new AccessDeniedException("Only the donor can edit this donation.");if(!"AVAILABLE".equals(d.getStatus()))throw new IllegalArgumentException("Only available donations can be edited.");if(input.getFoodName()==null||input.getFoodName().isBlank()||input.getLocation()==null||input.getLocation().isBlank()||input.getQuantity()==null||input.getQuantity()<1)throw new IllegalArgumentException("Food name, location and a quantity greater than zero are required.");d.setFoodName(input.getFoodName());d.setDescription(input.getDescription());d.setQuantity(input.getQuantity());d.setLocation(input.getLocation());d.setPickupDate(input.getPickupDate());d.setPickupTime(input.getPickupTime());return donations.save(d);}
}
